<script setup lang="ts">
import CanteenOrderCard from './CanteenOrderCard.vue';import {connectCanteen} from './realtime';
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import AdminDialog from '../../AdminDialog.vue';import './canteen.css';
const props=defineProps<{csrf?:string}>();const companies=ref<any[]>([]),company=ref(''),data=ref<any>(null),section=ref('dashboard'),error=ref(''),message=ref(''),busy=ref(false),initializing=ref(true),editor=ref<any>(null),resource=ref('');const orderView=ref(localStorage.getItem('judibas-canteen-order-view')==='list'?'list':'grid'),orderStatus=ref('');function setOrderView(value:string){orderView.value=value;localStorage.setItem('judibas-canteen-order-view',value);}
const kitchenTarget=ref(''),kitchenStatus=ref('confirmed'),orders=ref<any[]>([]),orderPage=ref(1),orderTotal=ref(0),report=ref<any>(null),audits=ref<any[]>([]),auditPage=ref(1),auditTotal=ref(0),search=ref(''),auditSearch=ref('');let catalogVersion=0;let disconnectRealtime:(()=>void)|undefined;let ordersSync:number|undefined;
const role=computed(()=>companies.value.find(c=>String(c.id)===company.value)?.role||'employee');const admin=computed(()=>role.value==='admin');const sections=computed(()=>admin.value?['dashboard','menu','orders','employees','levels','categories','items','stock','settings','reports','audit']:role.value==='employee'?['menu','orders']:role.value==='cashier'?['orders','reports']:['orders','kitchen-order']);const labels:Record<string,string>={dashboard:'Overview',menu:'Order a meal',orders:'Orders',employees:'Employee benefits',levels:'Benefit levels',categories:'Categories',items:'Menu & stock',stock:'Stock history',settings:'Settings',reports:'Reports',audit:'Audit history','kitchen-order':'Create employee order'};
const cart=ref<Record<number,number>>({}),quote=ref<any>(null),requestKey=ref<string|null>(null);const today=new Date().toLocaleDateString('en-CA'),from=ref(today),to=ref(today),groupBy=ref('employee'),reportLevel=ref(''),reportCategory=ref(''),reportEmployee=ref(''),reportItem=ref('');const title=computed(()=>labels[section.value]||'Canteen');const orderProfile=computed(()=>section.value==='kitchen-order'?data.value?.employees.find((e:any)=>String(e.user_id)===kitchenTarget.value):data.value?.profile);const currentLevel=computed(()=>data.value?.levels.find((l:any)=>l.id===orderProfile.value?.level_id));const menu=computed(()=>data.value?.items.filter((item:any)=>item.active&&data.value.categories.some((c:any)=>c.id===item.category_id&&c.active)&&item.name.toLowerCase().includes(search.value.toLowerCase()))||[]);const cartLines=computed(()=>Object.entries(cart.value).filter(([,quantity])=>quantity>0).map(([id,quantity])=>({item_id:Number(id),quantity})));const lowStock=computed(()=>data.value?.items.filter((i:any)=>i.stock_enabled&&i.stock_quantity<=i.low_stock_threshold)||[]);
async function api(path:string,method='GET',body?:any){const response=await fetch('/canteen/api/'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const result=await response.json();if(!response.ok)throw Error(Object.values(result.errors||{}).flat().join(' ')||result.message||'Unable to complete this action.');return result;}
async function catalog(){const version=++catalogVersion;const result=await api('catalog?company_id='+company.value+(section.value==='kitchen-order'&&kitchenTarget.value?'&target_user_id='+kitchenTarget.value:''));if(version===catalogVersion)data.value=result;}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function changeCompany(){cart.value={};quote.value=null;requestKey.value=null;data.value=null;editor.value=null;orders.value=[];report.value=null;audits.value=[];reportLevel.value='';reportCategory.value='';reportEmployee.value='';reportItem.value='';section.value=admin.value?'dashboard':role.value==='employee'?'menu':'orders';await action(async()=>{await catalog();await loadSection();});}
async function loadOrders(page=1){const result=await api('orders?company_id='+company.value+'&page='+page+'&status='+orderStatus.value);orders.value=result.data;orderTotal.value=result.total;orderPage.value=result.current_page;}
const reportQuery=()=>new URLSearchParams({company_id:company.value,from:from.value,to:to.value,group_by:groupBy.value,level_id:reportLevel.value,category_id:reportCategory.value,user_id:reportEmployee.value,item_id:reportItem.value}).toString();const appliedReportQuery=ref('');
async function loadReport(page=1,useApplied=false){const query=useApplied?appliedReportQuery.value:reportQuery();report.value=await api('reports?'+query+'&page='+page);appliedReportQuery.value=query;}
const stockRows=ref<any[]>([]),stockPage=ref(1),stockTotal=ref(0);
async function loadStock(page=1){const result=await api('stock?company_id='+company.value+'&page='+page);stockRows.value=result.data;stockPage.value=result.current_page;stockTotal.value=result.total;}
async function loadAudit(page=1){const result=await api('audit?company_id='+company.value+'&page='+page);audits.value=result.data;auditPage.value=result.current_page;auditTotal.value=result.total;}
const visibleAudits=computed(()=>audits.value.filter((entry:any)=>!auditSearch.value||[entry.action,entry.actor,entry.details].join(' ').toLowerCase().includes(auditSearch.value.toLowerCase())));
const auditLabel=(action:string)=>action.split('.').map((part:string)=>part.replace(/_/g,' ')).join(' / ').replace(/\b\w/g,(c:string)=>c.toUpperCase());
const stockChangeLabel=(row:any)=>row.quantity_change>0?`${row.quantity_change} added`:row.quantity_change<0?`${Math.abs(row.quantity_change)} sold`:'No change';
const auditSummary=(entry:any)=>{let d:any={};try{d=JSON.parse(entry.details||'{}')}catch{};const a=entry.action||'';if(a==='order.confirmed')return `Order #${d.order_id||'unknown'} was confirmed`;if(a==='order.updated')return `Order #${d.order_id||'unknown'} was updated`;if(a==='receipt.opened')return `Receipt opened for order #${d.order_id||'unknown'}`;if(a==='report.exported')return `Report exported (${String(d.format||'file').toUpperCase()})`;if(a.includes('stock'))return `Stock record updated${d.item_id?` for item #${d.item_id}`:''}`;if(a.includes('access'))return 'Employee Canteen access was updated';if(a.includes('initialized'))return 'Canteen setup was initialized';return auditLabel(a)};
async function loadSection(){if(section.value==='orders')await loadOrders();if(section.value==='reports'||section.value==='dashboard')await loadReport();if(section.value==='audit')await loadAudit();if(section.value==='stock')await loadStock();}
async function ensureRealtime(){disconnectRealtime?.();disconnectRealtime=await connectCanteen(company.value,props.csrf||'',()=>{if(section.value==='orders'&&!busy.value)void loadOrders(orderPage.value);});}function navigate(value:string){section.value=value;search.value='';error.value='';message.value='';editor.value=null;if(value==='orders')void ensureRealtime();void action(loadSection);}
function edit(type:string,row?:any){resource.value=type;error.value='';editor.value=row?JSON.parse(JSON.stringify(row)):type==='levels'?{name:'',company_percent:50,active:true}:type==='categories'?{name:'',active:true}:type==='items'?{name:'',category_id:'',price:0,active:true,available_from:'',available_to:'',stock_enabled:true,stock_quantity:0,low_stock_threshold:5,stock_reason:'Opening stock',rules:[]}:type==='settings'?{within_allowance_mode:'',excess_mode:'level_share',ordering_enabled:false,timezone:'Asia/Karachi',...data.value?.settings}:{};if(type==='items'){editor.value.available_from=editor.value.available_from?.slice(0,5)||'';editor.value.available_to=editor.value.available_to?.slice(0,5)||'';editor.value.stock_reason=row?'':'Opening stock';if(row)editor.value.expected_stock_quantity=row.stock_quantity;}}
function ruleToggle(level:number,event:Event){if((event.target as HTMLInputElement).checked)editor.value.rules.push({level_id:level,quantity_limit:null,period:'day',company_percent:null});else editor.value.rules=editor.value.rules.filter((r:any)=>r.level_id!==level);}
function save(){void action(async()=>{const values={...editor.value,company_id:Number(company.value)};if(resource.value==='items'){values.available_from||=null;values.available_to||=null;}await api('catalog/'+resource.value+(values.id?'/'+values.id:''),'POST',values);editor.value=null;await catalog();message.value='Changes saved.';});}
function quantity(id:number,delta:number){cart.value={...cart.value,[id]:Math.max(0,Math.min(100,(cart.value[id]||0)+delta))};quote.value=null;requestKey.value=null;}
function selectKitchenTarget(){cart.value={};quote.value=null;requestKey.value=null;void action(catalog);}function orderContext(){return section.value==='kitchen-order'?{target_user_id:Number(kitchenTarget.value),initial_status:kitchenStatus.value}:{};}function review(){void action(async()=>{quote.value=await api('quote','POST',{company_id:Number(company.value),lines:cartLines.value,...orderContext()});});}
function confirmOrder(){void action(async()=>{requestKey.value||=crypto.randomUUID();let result:any;try{result=await api('orders','POST',{company_id:Number(company.value),lines:cartLines.value,request_key:requestKey.value,quote_token:quote.value.quote_token,...orderContext()});}catch(e){quote.value=null;throw e;}cart.value={};quote.value=null;requestKey.value=null;await catalog();section.value='orders';await loadOrders();message.value='Order #'+result.order.id+' confirmed.';});}
function updateOrder(id:number,changes:any){void action(async()=>{await api('orders/'+id,'PATCH',changes);await loadOrders(orderPage.value);message.value='Order updated.';});}
function money(value:any){return 'Rs '+Number(value||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});}
const exportHref=(format:string)=>'/canteen/api/reports/export/'+format+'?'+appliedReportQuery.value;
const countLabel=(group:string)=>['item','category'].includes(group)?'Total units':'Number of orders';
onMounted(async()=>{ordersSync=window.setInterval(()=>{if(section.value==='orders'&&!busy.value)void loadOrders(orderPage.value);},1000);try{companies.value=(await api('bootstrap')).companies;if(companies.value.length){company.value=String(companies.value[0].id);await changeCompany();await ensureRealtime();}}catch(e){error.value=(e as Error).message;}finally{initializing.value=false;}});onUnmounted(()=>{disconnectRealtime?.();if(ordersSync)window.clearInterval(ordersSync);});
</script>
<template><section class="canteen-workspace"><header class="canteen-heading"><div><span class="canteen-eyebrow">JUDIBAS / EMPLOYEE BENEFITS</span><h1>Canteen</h1><p>Meals, benefits and daily operations in one place.</p></div><label>Company<select v-model="company" :disabled="busy" @change="changeCompany"><option v-for="c in companies" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label></header><p v-if="error" role="alert" class="notice admin-error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><div v-if="initializing" class="canteen-empty" role="status">Loading your canteen...</div><p v-else-if="!companies.length" class="canteen-empty">No company assigned. Contact your administrator.</p><div v-else class="canteen-layout"><nav class="canteen-navigation" aria-label="Canteen sections"><button v-for="value in sections" :key="value" :class="{active:section===value}" :aria-current="section===value?'page':undefined" :disabled="busy" @click="navigate(value)">{{labels[value]}}</button></nav><main class="canteen-content" :aria-busy="busy"><div class="canteen-section-heading"><div><h2>{{title}}</h2><small>{{role==='admin'?'Canteen administration':role==='employee'?'Your company benefits':role==='cashier'?'Cashier workspace':'Kitchen workspace'}}</small></div><button v-if="admin&&['levels','categories','items'].includes(section)" class="button primary" :disabled="busy" @click="edit(section)">Create {{section==='levels'?'level':section==='categories'?'category':'item'}}</button><button v-if="section==='orders'" class="button" :disabled="busy" @click="action(()=>loadOrders(orderPage))">Refresh orders</button></div>
<template v-if="data&&section==='dashboard'"><div class="canteen-stats"><article v-for="(label,key) in {orders:'Orders',employees:'Employees served',gross:'Total sales',company_share:'Company pays',employee_share:'Employee pays'}" :key="key"><span>{{label}}</span><strong>{{key==='orders'||key==='employees'?report?.summary[key]||0:money(report?.summary[key])}}</strong></article></div><div class="canteen-panel"><h3>Company setup</h3><p>{{data.settings?.ordering_enabled?'Ordering is enabled.':'Ordering is paused. Configure benefit levels, item eligibility and company settings before enabling orders.'}}</p><button v-if="!data.levels.length" class="button primary" :disabled="busy" @click="action(async()=>{await api('setup','POST',{company_id:Number(company)});await catalog();message='Initial levels and categories created.';})">Initialize levels and categories</button><button class="button" @click="navigate('settings')">Open settings</button></div><div class="canteen-panel"><h3>Low stock</h3><p v-if="!lowStock.length">No low-stock items.</p><div v-for="item in lowStock" :key="item.id" class="canteen-list-row"><strong>{{item.name}}</strong><span>{{item.stock_quantity}} remaining</span><button class="button" @click="edit('items',item)">Update stock</button></div></div></template>
<template v-if="data&&(section==='menu'||section==='kitchen-order')"><div v-if="section==='kitchen-order'" class="canteen-panel kitchen-order-target"><label>Order for employee<select v-model="kitchenTarget" @change="selectKitchenTarget"><option value="" disabled>Select an employee</option><option v-for="employee in data.employees" :key="employee.user_id" :value="String(employee.user_id)">{{employee.name}}</option></select></label><label>Initial status<select v-model="kitchenStatus"><option value="confirmed">Confirmed</option><option value="preparing">Preparing</option><option value="ready">Ready</option></select></label></div><div v-if="!orderProfile?.level_id" class="canteen-empty">Your administrator must assign a benefit level before you can order.</div><div v-else class="canteen-benefit-summary"><strong>{{currentLevel?.name}}</strong><span>Company share: {{currentLevel?.company_percent}}%</span><span>Employee share: {{100-(currentLevel?.company_percent||0)}}%</span></div><p v-if="!data.settings?.ordering_enabled" class="notice">Ordering is currently paused for this company.</p><div class="canteen-order-layout"><div><label class="canteen-search">Find a meal<input v-model="search" type="search" placeholder="Search menu..."></label><div class="canteen-menu-grid"><article v-for="item in menu" :key="item.id" class="canteen-menu-card"><span class="canteen-eyebrow">{{data.categories.find((c:any)=>c.id===item.category_id)?.name}}</span><h3>{{item.name}}</h3><strong>{{money(item.price)}}</strong><small v-if="item.stock_enabled">{{item.stock_quantity}} available</small><small v-if="currentLevel&&!item.rules.some((r:any)=>r.level_id===currentLevel.id)">Outside level benefits - employee pays full price</small><small v-else-if="item.allowance">{{item.allowance.limit===null?'Unlimited':Math.max(0,item.allowance.limit-item.allowance.used)+' remaining'}} / {{item.allowance.period}}</small><div class="canteen-quantity"><button :disabled="busy||!cart[item.id]" :aria-label="'Remove '+item.name" @click="quantity(item.id,-1)">-</button><span>{{cart[item.id]||0}}</span><button :disabled="busy||!data.settings?.ordering_enabled||!orderProfile?.eligible||!orderProfile?.level_id||(item.stock_enabled&&(cart[item.id]||0)>=item.stock_quantity)" :aria-label="'Add '+item.name" @click="quantity(item.id,1)">+</button></div></article></div><p v-if="!menu.length" class="canteen-empty">No menu items available.</p></div><aside class="canteen-panel canteen-cart"><h3>Your order</h3><div v-for="line in cartLines" :key="line.item_id" class="canteen-list-row"><span>{{data.items.find((i:any)=>i.id===line.item_id)?.name}}</span><strong>{{line.quantity}}</strong></div><p v-if="!cartLines.length">Choose an item to get started.</p><template v-if="quote"><div class="canteen-list-row"><span>Total</span><strong>{{money(quote.gross)}}</strong></div><div class="canteen-list-row"><span>Company pays</span><strong>{{money(quote.company_share)}}</strong></div><div class="canteen-list-row"><span>You pay at cashier</span><strong>{{money(quote.employee_share)}}</strong></div><button class="button primary" :disabled="busy" @click="confirmOrder">Confirm order</button></template><button v-else class="button primary" :disabled="busy||!cartLines.length" @click="review">Review payable amount</button></aside></div></template>
<template v-if="section==='orders'"><div class="canteen-orders-toolbar"><label>Status<select v-model="orderStatus" :disabled="busy" @change="action(()=>loadOrders())"><option value="">All orders</option><option v-for="status in ['confirmed','preparing','ready','delivered','cancelled']" :key="status" :value="status">{{status.charAt(0).toUpperCase()+status.slice(1)}}</option></select></label><div class="canteen-order-view-switch" role="group" aria-label="Order view"><button type="button" :aria-pressed="orderView==='grid'" @click="setOrderView('grid')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z"/></svg>Grid</button><button type="button" :aria-pressed="orderView==='list'" @click="setOrderView('list')"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M8 5h13 M8 12h13 M8 19h13 M3 5h1 M3 12h1 M3 19h1"/></svg>List</button></div></div><div class="canteen-orders" :class="'view-'+orderView"><CanteenOrderCard v-for="order in orders" :key="order.id" :order="order" :role="role" :busy="busy" @update="updateOrder"/></div><p v-if="!orders.length&&!busy" class="canteen-empty">{{orderStatus?'No orders match this status.':'No orders yet.'}}</p><div class="canteen-pagination"><button class="button" :disabled="busy||orderPage===1" @click="action(()=>loadOrders(orderPage-1))">Previous</button><span>{{orderTotal}} orders &middot; Page {{orderPage}}</span><button class="button" :disabled="busy||orderPage*20>=orderTotal" @click="action(()=>loadOrders(orderPage+1))">Next</button></div></template>
<template v-if="data&&admin&&['levels','categories','items','employees'].includes(section)"><div class="canteen-panel canteen-table-scroll"><table><thead><tr><th>Name</th><th>{{section==='employees'?'Benefit level':section==='items'?'Price':section==='levels'?'Company share':'Status'}}</th><th>{{section==='items'?'Stock':'Status'}}</th><th>Actions</th></tr></thead><tbody><tr v-for="row in data[section]" :key="row.id"><td><strong>{{row.name}}</strong><small v-if="row.email">{{row.email}}</small></td><td>{{section==='employees'?data.levels.find((l:any)=>l.id===row.level_id)?.name||'Not assigned':section==='items'?money(row.price):section==='levels'?row.company_percent+'%':row.active?'Active':'Inactive'}}</td><td><span class="canteen-badge">{{section==='items'?(row.stock_enabled?row.stock_quantity+' remaining':'Not tracked'):section==='employees'?(row.eligible?'Eligible':'Employee pays full price'):(row.active?'Active':'Inactive')}}</span></td><td><button class="button" :aria-label="'Edit '+row.name" @click="edit(section==='employees'?'profiles':section,row)">Edit</button></td></tr><tr v-if="!data[section].length"><td colspan="4">{{section==='employees'?'Create or invite users from Judibas Administration and assign Canteen access.':'No records yet.'}}</td></tr></tbody></table></div></template>
<div v-if="data&&section==='settings'&&admin" class="canteen-panel"><h3>Company ordering policy</h3><p>Choose how benefits apply before and after an allowance is used. Levels set the default contribution percentages; item rules may override them.</p><dl><dt>Within allowance</dt><dd>{{data.settings?.within_allowance_mode==='free'?'Employee pays nothing':data.settings?.within_allowance_mode==='level_share'?'Company and employee share the price':'Not configured'}}</dd><dt>After allowance</dt><dd>{{({level_share:'Use contribution split',full_price:'Employee pays full price',block:'Block excess orders'} as any)[data.settings?.excess_mode]||'Not configured'}}</dd><dt>Ordering</dt><dd>{{data.settings?.ordering_enabled?'Enabled':'Paused'}}</dd></dl><button class="button primary" @click="edit('settings')">Configure policy</button><h3 class="canteen-subheading">Receipt printing</h3><p>Kitchen and cashier receipts are available from each order. Use the print dialog to select the appropriate printer. Automatic routing to two printers will require a local printer connector.</p></div>
<template v-if="section==='reports'"><form class="canteen-panel canteen-report-filter" @submit.prevent="action(()=>loadReport())"><label>From<input v-model="from" type="date" required></label><label>To<input v-model="to" type="date" :min="from" required></label><label>Report view<select v-model="groupBy"><option value="order">Detailed orders</option><option value="item">Item</option><option value="category">Category</option><option value="employee">Employee</option><option value="level">Benefit level</option><option value="day">Day</option></select></label><label>Benefit level<select v-model="reportLevel"><option value="">All levels</option><option v-for="l in data?.levels" :key="l.id" :value="String(l.id)">{{l.name}}</option></select></label><label>Category<select v-model="reportCategory"><option value="">All categories</option><option v-for="c in data?.categories" :key="c.id" :value="String(c.id)">{{c.name}}</option></select></label><label v-if="admin">Employee<select v-model="reportEmployee" @change="reportEmployee && (groupBy='order')"><option value="">All employees</option><option v-for="e in data?.employees" :key="e.user_id" :value="String(e.user_id)">{{e.name}}</option></select></label><label>Item<select v-model="reportItem"><option value="">All items</option><option v-for="i in data?.items" :key="i.id" :value="String(i.id)">{{i.name}}</option></select></label><button class="button primary" :disabled="busy">Apply filters</button><a class="button" :href="exportHref('csv')">Export CSV</a><a class="button" :href="exportHref('xlsx')">Excel</a><a class="button" :href="exportHref('pdf')">PDF</a></form><div v-if="report" class="canteen-stats"><article v-for="(label,key) in {orders:report?.group_by==='order'?'Non-cancelled orders':'Total orders',employees:'Employees served',gross:'Total value',company_share:'Company contribution',employee_share:'Employee contribution'}" :key="key"><span>{{label}}</span><strong>{{key==='orders'||key==='employees'?report.summary[key]:money(report.summary[key])}}</strong></article></div><div v-if="report" class="canteen-report-guide"><p v-if="report.group_by==='order'">Each row is one separate order. Products show the quantity ordered in that transaction. Cancelled orders remain visible with zero payable amounts and are excluded from the summary. Item or category filters show only matching products and contributions.</p><p v-else-if="report.group_by==='employee'"><strong>Total units</strong> is the total quantity of that product. <strong>Number of orders</strong> is how many separate orders contained it.</p><p v-else>{{countLabel(report.group_by)==='Total units'?'Total units is the combined quantity of products ordered.':'Number of orders counts separate orders in each group.'}}</p><small v-if="report.group_by==='employee'">Example: 3 cups of Chai in one order + 1 cup in another = 4 total units across 2 orders. An order with multiple products is counted once in the Total orders summary.</small></div><template v-if="report && report.group_by==='order'"><div class="canteen-panel canteen-table-scroll"><table><thead><tr><th>Order / Date</th><th>Employee / Level</th><th>Products &amp; quantities</th><th>Units ordered</th><th>Total value</th><th>Company contribution</th><th>Employee contribution</th><th>Status / Payment</th></tr></thead><tbody><tr v-for="row in report.rows" :key="row.order_id"><td><a :href="'/canteen/orders/'+row.order_id+'/receipt/cashier'">#{{row.order_id}}</a><br><small>{{new Date(row.ordered_at).toLocaleString()}}</small></td><td>{{row.employee_name}}<br><span class="canteen-badge">{{row.level_name}}</span></td><td><div v-for="(product,index) in row.products" :key="index">{{product.name}} &times; {{product.quantity}}</div></td><td>{{row.item_quantity}}</td><td>{{money(row.gross)}}</td><td>{{money(row.company_share)}}</td><td>{{money(row.employee_share)}}</td><td><span class="canteen-badge">{{row.status}}</span><br><small>{{row.status==='cancelled'?'Not payable':row.payment_status.replaceAll('_',' ')}}</small></td></tr><tr v-if="!report.rows.length"><td colspan="8">No orders match these filters.</td></tr></tbody></table></div><div class="canteen-list-row"><span>{{report.total}} orders &middot; Page {{report.page}} of {{Math.max(1,Math.ceil(report.total/report.per_page))}}</span><button class="button" :disabled="busy || report.page<=1" @click="action(()=>loadReport(report.page-1,true))">Previous</button><button class="button" :disabled="busy || report.page*report.per_page>=report.total" @click="action(()=>loadReport(report.page+1,true))">Next</button></div></template><div v-if="report && report.group_by!=='order'" class="canteen-panel canteen-table-scroll"><table><thead><tr><th>{{report.group_by==='employee'?'Employee name':'Name / Date'}}</th><th v-if="report.group_by==='employee'">Benefit level</th><th v-if="report.group_by==='employee'">Ordered product</th><th v-if="report.group_by==='employee'">Total units</th><th>{{countLabel(report.group_by)}}</th><th>Total value</th><th>Company contribution</th><th>Employee contribution</th></tr></thead><tbody><tr v-for="(item,index) in report.rows" :key="index"><td>{{item.label}}</td><td v-if="report.group_by==='employee'"><span class="canteen-badge">{{item.level_name}}</span></td><td v-if="report.group_by==='employee'">{{item.product_name}}</td><td v-if="report.group_by==='employee'">{{item.item_quantity}}</td><td>{{item.quantity}}</td><td>{{money(item.gross)}}</td><td>{{money(item.company_share)}}</td><td>{{money(item.employee_share)}}</td></tr><tr v-if="!report.rows.length"><td :colspan="report.group_by==='employee'?8:5">No consumption for this period.</td></tr></tbody></table></div></template>
<template v-if="section==='stock'&&admin"><div class="canteen-panel canteen-table-scroll"><table><thead><tr><th>Item</th><th>Change</th><th>Balance</th><th>Reason</th><th>Order</th><th>Date</th></tr></thead><tbody><tr v-for="row in stockRows" :key="row.id"><td>{{row.item_name}}</td><td>{{row.quantity_change>0?'+':''}}{{row.quantity_change}}</td><td>{{row.balance}}</td><td>{{row.reason}}</td><td>{{row.order_id||'-'}}</td><td>{{new Date(row.created_at).toLocaleString()}}</td></tr><tr v-if="!stockRows.length"><td colspan="6">No stock movements yet.</td></tr></tbody></table></div><div class="canteen-pagination"><button class="button" :disabled="busy||stockPage===1" @click="action(()=>loadStock(stockPage-1))">Previous</button><span>{{stockTotal}} movements · Page {{stockPage}}</span><button class="button" :disabled="busy||stockPage*25>=stockTotal" @click="action(()=>loadStock(stockPage+1))">Next</button></div></template><template v-if="section==='audit'&&admin"><div v-for="entry in audits" :key="entry.id" class="canteen-panel"><strong>{{auditSummary(entry)}}</strong><p>{{entry.actor||'System'}} · {{new Date(entry.created_at).toLocaleString()}}</p><details><summary>Technical details</summary><pre>{{JSON.stringify(JSON.parse(entry.details||'{}'),null,2)}}</pre></details></div><p v-if="!audits.length" class="canteen-empty">No audit events yet.</p><div class="canteen-pagination"><button class="button" :disabled="busy||auditPage===1" @click="action(()=>loadAudit(auditPage-1))">Previous</button><span>{{auditTotal}} events · Page {{auditPage}}</span><button class="button" :disabled="busy||auditPage*25>=auditTotal" @click="action(()=>loadAudit(auditPage+1))">Next</button></div></template>
</main></div>
<AdminDialog v-if="editor" :title="resource==='profiles'?'Employee benefits':resource==='settings'?'Company policy':(editor.id?'Edit ':'Create ')+(resource==='items'?'menu item':resource==='levels'?'benefit level':'category')" :busy="busy" @close="!busy&&(editor=null)"><form class="admin-editor" @submit.prevent="save"><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div class="admin-form-grid"><template v-if="['levels','categories','items'].includes(resource)"><label>Name<input v-model="editor.name" required :maxlength="resource==='items'?150:100"></label><label class="check"><input v-model="editor.active" type="checkbox">Active</label></template><label v-if="resource==='levels'">Company contribution (%)<input v-model.number="editor.company_percent" type="number" min="0" max="100" required><small>Employee pays {{100-editor.company_percent}}% when the contribution split applies.</small></label><template v-if="resource==='items'"><label>Category<select v-model.number="editor.category_id" required><option disabled value="">Select category</option><option v-for="c in data.categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Price (Rs)<input v-model.number="editor.price" type="number" min="0" step="0.01" required></label><label>Available from<input v-model="editor.available_from" type="time"></label><label>Available until<input v-model="editor.available_to" type="time"></label><label class="check"><input v-model="editor.stock_enabled" type="checkbox">Track stock / prepared portions</label><label>Stock quantity<input v-model.number="editor.stock_quantity" type="number" min="0" step="1" required></label><label>Low-stock threshold<input v-model.number="editor.low_stock_threshold" type="number" min="0" step="1" required></label><label>Stock adjustment reason<input v-model="editor.stock_reason" maxlength="250" placeholder="Delivery received, stock correction..."></label></template><template v-if="resource==='profiles'"><label>Benefit level<select v-model="editor.level_id"><option :value="null">Not assigned</option><option v-for="l in data.levels" :key="l.id" :value="l.id">{{l.name}}</option></select></label><label class="check"><input v-model="editor.eligible" type="checkbox">Eligible for Canteen benefits</label></template><template v-if="resource==='settings'"><label>Company timezone<input v-model="editor.timezone" required placeholder="Asia/Karachi"><small>Controls allowance resets and availability times.</small></label><label>Within allowance<select v-model="editor.within_allowance_mode" required><option disabled value="">Choose policy</option><option value="free">Company pays 100% (free for employee)</option><option value="level_share">Use company / employee contribution split</option></select></label><label>After allowance<select v-model="editor.excess_mode" required><option value="level_share">Use contribution split</option><option value="full_price">Employee pays full price</option><option value="block">Block additional consumption</option></select></label><label class="check"><input v-model="editor.ordering_enabled" type="checkbox">Enable ordering</label></template></div><fieldset v-if="resource==='items'" class="canteen-rule-editor"><legend>Eligible levels and allowances</legend><p>Selected levels receive benefits under the configured allowance policy. Other levels can order at full employee price. A blank limit means unlimited quantities.</p><div class="canteen-level-rule-list"><article v-for="level in data.levels" :key="level.id" class="canteen-level-rule-card" :class="{selected:editor.rules.some((r:any)=>r.level_id===level.id)}"><div class="canteen-level-rule-heading"><label class="check"><input type="checkbox" :checked="editor.rules.some((r:any)=>r.level_id===level.id)" @change="ruleToggle(level.id,$event)"><strong>{{level.name}}</strong></label><span>{{editor.rules.some((r:any)=>r.level_id===level.id)?'Default split: Company '+level.company_percent+'% / Employee '+(100-level.company_percent)+'%':'Employee pays full price'}}</span></div><div v-for="rule in editor.rules.filter((r:any)=>r.level_id===level.id)" :key="rule.level_id" class="canteen-level-rule-fields"><label>Quantity allowance<input v-model.number="rule.quantity_limit" type="number" min="0" placeholder="Unlimited" @change="rule.quantity_limit=rule.quantity_limit===''?null:rule.quantity_limit"><small>Leave blank for unlimited.</small></label><label>Period<select v-model="rule.period"><option value="day">Daily</option><option value="week">Weekly</option><option value="month">Monthly</option></select></label><label>Company % override<input v-model.number="rule.company_percent" type="number" min="0" max="100" :placeholder="'Use level ('+level.company_percent+'%)'" @change="rule.company_percent=rule.company_percent===''?null:rule.company_percent"><small>Optional item-specific percentage.</small></label></div></article></div></fieldset><div class="editor-actions"><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button><button class="button primary" :disabled="busy">Save</button></div></form></AdminDialog></section></template>
